import{_ as i,a as r,b as o,c as t,d,e as s,f as n,g as c,h as l,i as m,j as _,k as u,l as p,m as h,n as g,o as k,p as a,q as v,r as w,s as f}from"./chunks/chaumet-vendome-jewelry.Cm4SgExd.js";import{_ as y,o as b,c as q,a5 as C}from"./chunks/framework.BF53ZjCA.js";const T=JSON.parse('{"title":"The Maison Archive","description":"","frontmatter":{"title":"The Maison Archive","gallery":"by-house"},"headers":[],"relativePath":"gallery/by-house.md","filePath":"gallery/by-house.md","lastUpdated":1789155237000}'),S={name:"gallery/by-house.md"};function j(A,e,G,F,B,O){return b(),q("div",null,[...e[0]||(e[0]=[C('<h1 id="the-maison-archive" tabindex="-1">The Maison Archive <a class="header-anchor" href="#the-maison-archive" aria-label="Permalink to &quot;The Maison Archive&quot;">​</a></h1><div class="maison-archive-hero"><p>A first-edition archive of seven legendary maisons. Each house is represented by three object records: one for heritage, one for signature craft, and one for the gemstone itself. Related cards may describe the same object from different states or viewpoints; every bundled image has a traceable source and recorded reuse terms.</p><div class="maison-archive-hero__meta"><span>21 works</span><span>7 maisons</span><span>Selection rule: heritage · signature craft · gemstone focus</span></div></div><h2 id="browse-by-maison" tabindex="-1">Browse by maison <a class="header-anchor" href="#browse-by-maison" aria-label="Permalink to &quot;Browse by maison&quot;">​</a></h2><p class="maison-archive-guide">Browse 21 object records by maison. Open any image to inspect its original file page, author, institution, and reuse terms; an “Archive relation” note marks a related view, not automatically a separate work.</p><nav class="maison-index" aria-label="Maison index"><a href="#cartier">Cartier</a><a href="#vca">Van Cleef &amp; Arpels</a><a href="#boucheron">Boucheron</a><a href="#tiffany">Tiffany &amp; Co.</a><a href="#harry-winston">Harry Winston</a><a href="#graff">Graff</a><a href="#chaumet">Chaumet</a></nav><section class="maison-section" id="cartier"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1847</p><h2>Cartier</h2></div><p>carved colour · panther · Art Deco</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Tutti_frutti_bracelet_-_Cartier_(25802475508).jpg" target="_blank" rel="noreferrer"><img src="'+i+`" alt="Tutti Frutti Bracelet" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>1928</time></div><h3>Tutti Frutti Bracelet</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>ruby · emerald · sapphire</dd></div><div><dt>Craft</dt><dd>carved coloured gemstones</dd></div><div><dt>Style</dt><dd>Art Deco botanical</dd></div></dl><p>Carved rubies, emeralds, and sapphires form a botanical composition that defines Cartier&#39;s coloured-gem vocabulary.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://www.cartier.com/en-gb/maison/the-story/living-heritage/the-cartier-collection/jewellery&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Linked_bracelet_-_Cartier_(25891095068).jpg" target="_blank" rel="noreferrer"><img src="`+r+`" alt="Linked Bracelet" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>1920s</time></div><h3>Linked Bracelet</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>articulated platinum links</dd></div><div><dt>Style</dt><dd>Jazz Age geometry</dd></div></dl><p>Articulated links turn a geometric Art Deco rhythm into a wearable, flexible structure.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://www.cartier.com/en-gb/maison/the-story/living-heritage/the-cartier-collection/jewellery&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Joyaux_dynastiques_H%C3%B4tel_de_la_Marine_broche_noeud_dentelle_diamants_platine_or.jpg" target="_blank" rel="noreferrer"><img src="`+o+`" alt="Lace-Knot Diamond Brooch" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>1906</time></div><h3>Lace-Knot Diamond Brooch</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>lace-knot diamond setting</dd></div><div><dt>Style</dt><dd>Belle Époque formal jewellery</dd></div></dl><p>A lace-like openwork silhouette organises diamonds and metal into a study of Cartier&#39;s light, formal structure.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Joyaux_dynastiques_H%C3%B4tel_de_la_Marine_broche_noeud_dentelle_diamants_platine_or.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><section class="maison-section" id="vca"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1906</p><h2>Van Cleef &amp; Arpels</h2></div><p>Mystery Set · nature · movement</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Loop_bracelet_-_Van_Cleef_and_Arpels_(39055602034).jpg" target="_blank" rel="noreferrer"><img src="`+t+`" alt="Loop Bracelet" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>1929</time></div><h3>Loop Bracelet</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>platinum and diamond geometry</dd></div><div><dt>Style</dt><dd>Cubist Art Deco</dd></div></dl><p>A 1920s geometric bracelet pairing step-cut stones with platinum structure and early VCA modernism.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://www.vam.ac.uk/collections/jewellery&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Ruby_necklace_-_Van_Cleef_and_Arpels_(38965252754).jpg" target="_blank" rel="noreferrer"><img src="`+d+`" alt="Ruby Necklace" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>20th century</time></div><h3>Ruby Necklace</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>ruby · diamond</dd></div><div><dt>Craft</dt><dd>articulated necklace construction</dd></div><div><dt>Style</dt><dd>colour-led high jewellery</dd></div></dl><p>Saturated ruby colour establishes the focal point while diamonds control contrast and visual layering.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://www.vam.ac.uk/collections/jewellery&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Pendant_watch_-_Van_Cleef_and_Arpels_(38772069405).jpg" target="_blank" rel="noreferrer"><img src="`+s+`" alt="Pendant Watch" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>1927</time></div><h3>Pendant Watch</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond · pearl</dd></div><div><dt>Craft</dt><dd>concealed watch movement and chatelaine form</dd></div><div><dt>Style</dt><dd>Jazz Age Cubism</dd></div></dl><p>A miniature watch, pearls, and chatelaine-like chains merge decoration with function in one compact object.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://www.vam.ac.uk/collections/jewellery&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><section class="maison-section" id="boucheron"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1858</p><h2>Boucheron</h2></div><p>open structure · fauna · colour</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Mackay_Necklace_Boucheron_1877.png" target="_blank" rel="noreferrer"><img src="`+n+`" alt="Mackay Sapphire and Diamond Necklace" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>1877</time></div><h3>Mackay Sapphire and Diamond Necklace</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>sapphire · diamond</dd></div><div><dt>Craft</dt><dd>sapphire and diamond necklace composition</dd></div><div><dt>Style</dt><dd>Belle Époque historic jewellery</dd></div></dl><p>A historic necklace made for the 1878 Paris exposition, showing Boucheron&#39;s early contrast between sapphire and diamond.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Mackay_Necklace_Boucheron_1877.png&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Collier_tuyau_%C3%A0_gaz,_PPO03791(1).jpg" target="_blank" rel="noreferrer"><img src="`+c+`" alt="Gas-Pipe Diamond Necklace" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>1945–1950</time></div><h3>Gas-Pipe Diamond Necklace</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>articulated tubular necklace with diamond ribbon</dd></div><div><dt>Style</dt><dd>mid-century architectural jewellery</dd></div></dl><p>A Petit Palais Boucheron necklace layers a lightweight articulated tube with a diamond ribbon to study structure and reflection.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Collier_tuyau_%C3%A0_gaz,_PPO03791(1).jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Boucheron,_devant_de_corsage,_1925,_oro_al_palladio,_lapislazzuli,_corallo,_giada,_onice,_turchese,_strass_(parigi,_coll._boucheron).jpg" target="_blank" rel="noreferrer"><img src="`+l+`" alt="1925 Coloured-Gemstone Corsage Ornament" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>1925</time></div><h3>1925 Coloured-Gemstone Corsage Ornament</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>lapis-lazuli · coral · jade · onyx · turquoise</dd></div><div><dt>Craft</dt><dd>multi-material corsage ornament construction</dd></div><div><dt>Style</dt><dd>Art Deco colour blocking</dd></div></dl><p>Lapis lazuli, coral, jade, onyx, and turquoise create layered colour blocks in a Boucheron stone-first study.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Boucheron,_devant_de_corsage,_1925,_oro_al_palladio,_lapislazzuli,_corallo,_giada,_onice,_turchese,_strass_(parigi,_coll._boucheron).jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><section class="maison-section" id="tiffany"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1837</p><h2>Tiffany &amp; Co.</h2></div><p>light · proportion · blue book</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Tiffany_setting.jpg" target="_blank" rel="noreferrer"><img src="`+m+`" alt="Tiffany Setting" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>1886</time></div><h3>Tiffany Setting</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>six-prong solitaire setting</dd></div><div><dt>Style</dt><dd>modern engagement icon</dd></div></dl><p>Raising the stone above the band to maximise light became a foundational product form for modern engagement rings.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Tiffany_setting.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Jean_schlumberger_per_tiffany_%26_co.,_spilla_fiocco_schlumberger,_con_acquamarina_da_148,5_carati,_diamanti,_platino_e_oro.jpg" target="_blank" rel="noreferrer"><img src="`+_+`" alt="Schlumberger Bow Brooch" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>20th century</time></div><h3>Schlumberger Bow Brooch</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>aquamarine · diamond</dd></div><div><dt>Craft</dt><dd>sculptural platinum ribbon setting</dd></div><div><dt>Style</dt><dd>organic modernism</dd></div></dl><p>A platinum ribbon-like structure wraps the centre stone, turning movement and tension into a sculptural setting.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Jean_schlumberger_per_tiffany_%26_co.,_spilla_fiocco_schlumberger,_con_acquamarina_da_148,5_carati,_diamanti,_platino_e_oro.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Tiffany_Diamond.jpg" target="_blank" rel="noreferrer"><img src="`+u+`" alt="Tiffany Yellow Diamond" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>1877</time></div><h3>Tiffany Yellow Diamond</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>yellow-diamond</dd></div><div><dt>Craft</dt><dd>cushion-cut diamond presentation</dd></div><div><dt>Style</dt><dd>iconic coloured diamond</dd></div></dl><p>An open-license view of the Tiffany Yellow Diamond foregrounds how a maison builds a narrative around one exceptional coloured stone.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Tiffany_Diamond.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><section class="maison-section" id="harry-winston"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1932</p><h2>Harry Winston</h2></div><p>diamond · cluster · scale</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Spanish_Inquisition_Necklace.jpg" target="_blank" rel="noreferrer"><img src="`+p+`" alt="Spanish Inquisition Necklace" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>before 1926</time></div><h3>Spanish Inquisition Necklace</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>emerald · diamond</dd></div><div><dt>Craft</dt><dd>graduated emerald and diamond necklace</dd></div><div><dt>Style</dt><dd>historic Indian-inspired grandeur</dd></div></dl><p>An emerald-and-diamond historic necklace later named by Harry Winston and documented through the Smithsonian collection.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://naturalhistory.si.edu/explore/collections/geogallery/10002801&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Spanish_Inquisition_Necklace_2.jpg" target="_blank" rel="noreferrer"><img src="`+h+`" alt="Cluster Setting" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>1940s</time></div><h3>Cluster Setting</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>floating cluster arrangement</dd></div><div><dt>Style</dt><dd>diamond-led naturalism</dd></div></dl><p>Diamonds set at varied angles create a continuous floral sparkle, one of Harry Winston&#39;s most recognisable design languages.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Spanish_Inquisition_Necklace_2.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:The_Hope_Diamond_(107006041).jpg" target="_blank" rel="noreferrer"><img src="`+g+`" alt="Hope Diamond · Winston Archive" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>1949–1958</time></div><h3>Hope Diamond · Winston Archive</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>historic diamond presentation and provenance</dd></div><div><dt>Style</dt><dd>diamond-led institutional archive</dd></div></dl><p>Harry Winston acquired the Hope Diamond in 1949 and donated it to the Smithsonian in 1958; this archive view links stone, display, and brand narrative.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:The_Hope_Diamond_(107006041).jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><section class="maison-section" id="graff"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1960</p><h2>Graff</h2></div><p>exceptional stones · provenance</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_diamond,_before_beeing_recut_by_Graff.png" target="_blank" rel="noreferrer"><img src="`+k+'" alt="Wittelsbach Diamond · Before Recut" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>17th century / recut 2008</time></div><h3>Wittelsbach Diamond · Before Recut</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>blue-diamond</dd></div><div><dt>Craft</dt><dd>historical diamond recutting</dd></div><div><dt>Style</dt><dd>exceptional coloured diamond</dd></div></dl><p>A public-domain archival view before recutting, useful for discussing gemstone history, cutting decisions, and brand narrative.</p><p class="maison-work-card__relation"><strong>Archive relation</strong>Read this with the Graff post-recut records as one stone across two cutting states.</p><a class="maison-work-card__source" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_diamond,_before_beeing_recut_by_Graff.png" target="_blank" rel="noreferrer">Open source ↗</a></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_Graff_Diamond.JPG" target="_blank" rel="noreferrer"><img src="'+a+'" alt="Wittelsbach Diamond · After Recut" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>2008 recut</time></div><h3>Wittelsbach Diamond · After Recut</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>blue-diamond</dd></div><div><dt>Craft</dt><dd>historical diamond recutting</dd></div><div><dt>Style</dt><dd>exceptional coloured diamond</dd></div></dl><p>An open-license post-recut view pairs with the earlier archive to study how Graff used cutting to renew visual and brand value; it is not a separate stone.</p><p class="maison-work-card__relation"><strong>Archive relation</strong>Same stone as the preceding record, shown after recutting as a before/after comparison.</p><a class="maison-work-card__source" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_Graff_Diamond.JPG" target="_blank" rel="noreferrer">Open source ↗</a></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_Graff_Diamond.JPG" target="_blank" rel="noreferrer"><img src="'+a+'" alt="Wittelsbach Diamond · Cutting Study Record" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>2008 recut</time></div><h3>Wittelsbach Diamond · Cutting Study Record</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>blue-diamond</dd></div><div><dt>Craft</dt><dd>precision faceting and provenance</dd></div><div><dt>Style</dt><dd>provenance-led luxury</dd></div></dl><p>The same open-license finished image is indexed here for a cutting study, separating a workshop record from the gemstone object; it is not another independent work.</p><p class="maison-work-card__relation"><strong>Archive relation</strong>Shares the post-recut image source as a related cutting-study view, not a separate object.</p><a class="maison-work-card__source" href="https://commons.wikimedia.org/wiki/File:Wittelsbach_Graff_Diamond.JPG" target="_blank" rel="noreferrer">Open source ↗</a></div></article></div></section><section class="maison-section" id="chaumet"><header class="maison-section__header"><div><p class="maison-section__kicker">MAISON · 1780</p><h2>Chaumet</h2></div><p>tiara · history · geometry</p></header><div class="maison-work-grid"><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Egyptian_brooch_-_Chaumet_(39643558802).jpg" target="_blank" rel="noreferrer"><img src="'+v+`" alt="Egyptian Brooch" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Heritage piece</span><time>1920s</time></div><h3>Egyptian Brooch</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond · emerald</dd></div><div><dt>Craft</dt><dd>geometric brooch construction</dd></div><div><dt>Style</dt><dd>Egyptian Revival</dd></div></dl><p>Egyptian Revival imagery meets geometric gemstone construction in a concise example of Chaumet&#39;s historical translation.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Egyptian_brooch_-_Chaumet_(39643558802).jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Tiara_with_brier_rose_and_jasmine_by_Chaumet.jpg" target="_blank" rel="noreferrer"><img src="`+w+`" alt="Brier Rose and Jasmine Tiara" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Signature craft</span><time>1830</time></div><h3>Brier Rose and Jasmine Tiara</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond · sapphire</dd></div><div><dt>Craft</dt><dd>floral tiara architecture</dd></div><div><dt>Style</dt><dd>Romantic historic jewellery</dd></div></dl><p>A 1830 Chaumet tiara by Jean-Baptiste Fossin translates brier rose and jasmine into a court-jewellery structure.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Tiara_with_brier_rose_and_jasmine_by_Chaumet.jpg&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article><article class="maison-work-card"><a class="maison-work-card__media" href="https://commons.wikimedia.org/wiki/File:Chaumet_vendome.JPG" target="_blank" rel="noreferrer"><img src="`+f+`" alt="Chaumet Vendôme Jewellery" loading="lazy"></a><div class="maison-work-card__body"><div class="maison-work-card__eyebrow"><span>Gemstone focus</span><time>20th century</time></div><h3>Chaumet Vendôme Jewellery</h3><dl class="maison-work-card__facts"><div><dt>Gems</dt><dd>diamond</dd></div><div><dt>Craft</dt><dd>diamond necklace construction</dd></div><div><dt>Style</dt><dd>Place Vendôme formal jewellery</dd></div></dl><p>An open-license finished Chaumet view adds a diamond-jewellery sample focused on necklace proportion, reflection, and wearability.</p><pre><code>&lt;a class=&quot;maison-work-card__source&quot; href=&quot;https://commons.wikimedia.org/wiki/File:Chaumet_vendome.JPG&quot; target=&quot;_blank&quot; rel=&quot;noreferrer&quot;&gt;Open source ↗&lt;/a&gt;
</code></pre></div></article></div></section><div class="maison-archive-note"><strong>Editorial boundary</strong><p>Object or work sources and image-rights sources are recorded separately. Every card uses a local image, with reuse details maintained on the [image credits page](../image-credits); related records for one object are labelled on the card.</p></div><p><em>Return to the <a href="./intro.html">gallery overview</a>.</em></p>`,14)])])}const P=y(S,[["render",j]]);export{T as __pageData,P as default};
